package io.github.vishalmysore.a2a.domain;

import com.fasterxml.jackson.annotation.JsonIgnore;

import lombok.Data;

import java.util.List;
import java.util.Map;

@Data

public class Message {

    @JsonIgnore
    private String id;

    private String role;


    private List<Part> parts;


    private Map<String, String> metadata;

    /**
     * Unique identifier for this message, generated by the sender.
     */
    private String messageId;

    /**
     * Identifier of the task this message belongs to, if any.
     */
    private String taskId;

    /**
     * Context identifier used to group related tasks and messages into one conversation.
     */
    private String contextId;

    /**
     * Identifiers of other tasks referenced by this message, used to provide additional context.
     */
    private List<String> referenceTaskIds;

    /**
     * URIs of A2A protocol extensions relevant to this message.
     */
    private List<String> extensions;
}
